// Firebase config, storage adapter, seeds, constants, small helpers
// (part of the UltraMed app script — the files under js/app load in order and share one global scope)
// ---- STORAGE BACKEND ----
// This app expects a `window.storage` API (get/set/list/delete). Fill in
// FIREBASE_CONFIG below (see README.md) to sync data across every device.
// Until then it falls back to this browser's localStorage only.
const APP_REV = 'v89'; // keep in step with sw.js CACHE version
const LOGO_DATAURI = 'data:image/png;base64,'; // official UltraMed primary logo (ultramedgcc.com), unmodified
document.getElementById('gateLogo').src = LOGO_DATAURI; // single embedded copy serves both the gate and the reports
const FIREBASE_CONFIG = {
  apiKey: "AIzaSyAlkAW4-Eq4LKXtVOSx0wdP_UMzxht5_r4",
  authDomain: "ultramed-field-ops.firebaseapp.com",
  projectId: "ultramed-field-ops",
  storageBucket: "ultramed-field-ops.firebasestorage.app",
  messagingSenderId: "562076174140",
  appId: "1:562076174140:web:c90047e64c220b83a38039"
};
const FIREBASE_ENABLED = !!(FIREBASE_CONFIG.apiKey && !FIREBASE_CONFIG.apiKey.startsWith('YOUR_'));

if(!window.storage){
  if(FIREBASE_ENABLED && window.firebase){
    firebase.initializeApp(FIREBASE_CONFIG);
    const db = firebase.firestore();
    const authReady = new Promise((resolve) => {
      firebase.auth().onAuthStateChanged(user => { if(user) resolve(user); });
    });
    window.storage = {
      // opts.server: answer from the server only — never from the SDK's
      // in-memory cache — for reads whose whole point is "what is in the
      // cloud RIGHT NOW" (the pre-read before a sales save).
      async get(key, _shared, opts){
        await authReady;
        const doc = await db.collection('state').doc(key).get(opts && opts.server ? { source: 'server' } : undefined);
        return doc.exists ? { value: doc.data().value } : null;
      },
      async set(key, value){
        await authReady;
        await db.collection('state').doc(key).set({ value, updated: Date.now() });
        return true;
      },
      // Several documents in ONE atomic commit: all land or none. A sales
      // upload writes its row chunks and the index together, so a save can
      // never half-land (chunks without an index, or an index pointing at
      // chunks that never arrived). Firestore caps a commit at 500 writes /
      // ~10 MB, far above a single upload; larger sets go in a few commits.
      async setMany(entries){
        await authReady;
        const now = Date.now();
        let batch = db.batch(), n = 0, bytes = 0;
        for(const [k, v] of entries){
          if(n >= 400 || bytes + v.length > 8e6){ await batch.commit(); batch = db.batch(); n = 0; bytes = 0; }
          batch.set(db.collection('state').doc(k), { value: v, updated: now }); n++; bytes += v.length;
        }
        if(n) await batch.commit();
        return true;
      },
      // Read-merge-write as ONE atomic step: the merge function sees the
      // document as it is on the server at commit time, and Firestore
      // retries it if another device wrote in between — so two phones
      // saving a visit within the same second can no longer drop one of
      // them. fn(cloudValueOrNull) → the new value, or null to refuse.
      async update(key, fn){
        await authReady;
        const ref = db.collection('state').doc(key);
        return db.runTransaction(async tx => {
          const doc = await tx.get(ref);
          const next = fn(doc.exists ? doc.data().value : null);
          if(next == null) return null;
          tx.set(ref, { value: next, updated: Date.now() });
          return next;
        });
      },
      async delete(key){
        await authReady;
        await db.collection('state').doc(key).delete();
        return true;
      },
      async list(prefix){
        await authReady;
        // Range query on the document id: only the matching ids travel. The
        // old whole-collection read downloaded every backup snapshot and
        // sales chunk in full just to list their names.
        const col = db.collection('state');
        const idPath = firebase.firestore.FieldPath.documentId();
        const q = prefix ? col.where(idPath, '>=', prefix).where(idPath, '<', prefix + '') : col;
        const snap = await q.get();
        const keys = [];
        snap.forEach(d => { if(d.id.startsWith(prefix)) keys.push(d.id); });
        return { keys };
      }
    };
    console.log('UltraMed Field Ops: syncing via Firebase Firestore');
  } else {
  if(!FIREBASE_ENABLED) console.log('UltraMed Field Ops: Firebase not configured — using local-only storage. See README.md to enable cross-device sync.');
  window.storage = (function(){
    const PREFIX = 'ultramed_';
    return {
      async get(key){
        const raw = localStorage.getItem(PREFIX + key);
        return raw === null ? null : { value: raw };
      },
      async set(key, value){
        localStorage.setItem(PREFIX + key, value);
        return true;
      },
      async update(key, fn){
        const cur = localStorage.getItem(PREFIX + key);
        const next = fn(cur === null ? null : cur);
        if(next == null) return null;
        localStorage.setItem(PREFIX + key, next);
        return next;
      },
      async setMany(entries){
        entries.forEach(([k, v]) => localStorage.setItem(PREFIX + k, v));
        return true;
      },
      async delete(key){
        localStorage.removeItem(PREFIX + key);
        return true;
      },
      async list(prefix){
        const keys = [];
        for(let i=0; i<localStorage.length; i++){
          const k = localStorage.key(i);
          if(k && k.startsWith(PREFIX + prefix)) keys.push(k.slice(PREFIX.length));
        }
        return { keys };
      }
    };
  })();
  }
}
