// Team roster lives in storage so it can be managed from the admin panel
// without touching code. REPS/USERS are derived views kept in sync with it.
const AVATARS = [
  'linear-gradient(140deg,#2E8B47,#0B3D22)','linear-gradient(140deg,#8FD4E8,#3E9BC4)',
  'linear-gradient(140deg,#B0AEF5,#5E5CE6)','linear-gradient(140deg,#F7C08A,#E8873F)',
  'linear-gradient(140deg,#F2A2C0,#D65C8E)','linear-gradient(140deg,#9FE3C8,#3FAE86)'
];
const STAFF_SEED = [
  {name:'Mariam',     role:'rep',        email:'mariam@ultramed-kw.com',  av:AVATARS[0]},
  {name:'Renova',     role:'rep',        email:'r.ayman@ultramed-kw.com', av:AVATARS[1]},
  {name:'Dr. Ghaith', role:'supervisor', email:'drgaith@ultramed-kw.com', av:AVATARS[2]}
];
let staff = STAFF_SEED.map(s=>({...s}));
let REPS = [];
let USERS = {};
function refreshStaff(){
  // REPS is the field sales team only — the supervisor is NOT a rep, so they
  // never appear as a phantom zero-row in targets/activity/scorecards, and are
  // never a target of ERP salesman→rep mapping or clinic assignment.
  REPS = staff.filter(s=>s.role==='rep').map(s=>s.name);
  USERS = {};
  staff.forEach(s=>{ USERS[s.name] = {role:s.role, email:s.email}; });
  // The login screen renders before anyone is authenticated, so the roster must
  // also live locally — otherwise a newly added member could never sign in.
  try{ localStorage.setItem('ultramed_staff_cache', JSON.stringify(staff)); }catch(e){}
}
try{
  const cached = localStorage.getItem('ultramed_staff_cache');
  if(cached){ const parsed = JSON.parse(cached); if(Array.isArray(parsed) && parsed.length) staff = parsed; }
}catch(e){}
refreshStaff();

